import * as crypto from 'crypto';
import * as fs from 'fs';

interface AuditEntry {
  timestamp: number;
  action: string;
  principal: string;
  checksum: string;
}

interface SerializationContext {
  allowedTypes: Set<string>;
  maxDepth: number;
  auditLog: AuditEntry[];
}

const HMAC_KEY = crypto.randomBytes(32);

function computeChecksum(data: string): string {
  return crypto.createHmac('sha256', HMAC_KEY).update(data).digest('hex');
}

function logAudit(ctx: SerializationContext, action: string, principal: string): void {
  const timestamp = Date.now();
  const entry: AuditEntry = {
    timestamp,
    action,
    principal,
    checksum: computeChecksum(`${timestamp}:${action}:${principal}`)
  };
  ctx.auditLog.push(entry);
}

class TypeRegistry {
  private registry: Map<string, { reviver: (data: any) => any }> = new Map();

  register(typeName: string, reviver: (data: any) => any): void {
    this.registry.set(typeName, { reviver });
  }

  getReviver(typeName: string): ((data: any) => any) | undefined {
    return this.registry.get(typeName)?.reviver;
  }

  hasType(typeName: string): boolean {
    return this.registry.has(typeName);
  }
}

const globalRegistry = new TypeRegistry();

globalRegistry.register('Date', (d: any) => new Date(d.iso));
globalRegistry.register('Buffer', (d: any) => Buffer.from(d.data, 'base64'));
globalRegistry.register('RegExp', (d: any) => new RegExp(d.source, d.flags));
globalRegistry.register('Map', (d: any) => new Map(d.entries));
globalRegistry.register('Set', (d: any) => new Set(d.values));

function validateType(typeName: string, ctx: SerializationContext): boolean {
  return ctx.allowedTypes.has(typeName) && globalRegistry.hasType(typeName);
}

function deserializeValue(node: any, ctx: SerializationContext, depth: number, path: string): any {
  if (depth > ctx.maxDepth) {
    throw new Error(`Max depth exceeded at path: ${path}`);
  }

  if (node === null || node === undefined) return node;
  if (typeof node !== 'object') return node;

  if (node.__type && node.__data) {
    const typeName = String(node.__type);
    if (!validateType(typeName, ctx)) {
      logAudit(ctx, 'BLOCKED_TYPE', typeName);
      throw new Error(`Type not allowed: ${typeName}`);
    }
    const reviver = globalRegistry.getReviver(typeName);
    if (!reviver) {
      throw new Error(`No reviver for type: ${typeName}`);
    }
    logAudit(ctx, 'REVIVE_TYPE', typeName);
    return reviver(deserializeValue(node.__data, ctx, depth + 1, `${path}.__data`));
  }

  if (node.__proto_chain && node.__payload) {
    return reconstructFromChain(node, ctx, depth, path);
  }

  if (Array.isArray(node)) {
    return node.map((item, i) => deserializeValue(item, ctx, depth + 1, `${path}[${i}]`));
  }

  const result: any = {};
  for (const key of Object.keys(node)) {
    if (key === '__proto__' || key === 'constructor' || key === 'prototype') {
      logAudit(ctx, 'BLOCKED_KEY', key);
      continue;
    }
    result[key] = deserializeValue(node[key], ctx, depth + 1, `${path}.${key}`);
  }
  return result;
}

function reconstructFromChain(node: any, ctx: SerializationContext, depth: number, path: string): any {
  const chain: string[] = node.__proto_chain;
  const payload = node.__payload;

  if (!Array.isArray(chain) || chain.length > 3) {
    logAudit(ctx, 'INVALID_CHAIN', JSON.stringify(chain).slice(0, 50));
    throw new Error('Invalid or too-long prototype chain');
  }

  for (const typeName of chain) {
    if (typeof typeName !== 'string' || !validateType(typeName, ctx)) {
      logAudit(ctx, 'BLOCKED_CHAIN_TYPE', String(typeName));
      throw new Error(`Chain type not allowed: ${typeName}`);
    }
  }

  logAudit(ctx, 'RECONSTRUCT_CHAIN', chain.join(' -> '));

  const result = deserializeValue(payload, ctx, depth + 1, `${path}.__payload`);

  for (let i = chain.length - 1; i >= 0; i--) {
    const reviver = globalRegistry.getReviver(chain[i]);
    if (reviver) {
      const revived = reviver(result);
      if (typeof revived === 'object' && revived !== null) {
        Object.freeze(revived);
      }
      return revived;
    }
  }
  return result;
}

function deserialize(json: string, principal: string): any {
  const ctx: SerializationContext = {
    allowedTypes: new Set(['Date', 'Buffer', 'RegExp', 'Map', 'Set']),
    maxDepth: 10,
    auditLog: []
  };

  logAudit(ctx, 'DESERIALIZE_START', principal);

  let parsed: any;
  try {
    parsed = JSON.parse(json);
  } catch (e) {
    logAudit(ctx, 'PARSE_ERROR', principal);
    throw new Error('Invalid JSON');
  }

  const result = deserializeValue(parsed, ctx, 0, '$');
  logAudit(ctx, 'DESERIALIZE_COMPLETE', principal);

  return { result, audit: ctx.auditLog };
}

export { deserialize, globalRegistry, TypeRegistry };
